INSERT INTO `mdl_course` VALUES (1,0,1,'Vilcom Networks Limited LMS','Vilcom LMS','','<p>Vilcom Networks Limited Learning Management System</p>',0,'site',1,3,0,0,0,0,0,0,0,1,1,NULL,0,0,0,'','','',1728293151,1728298183,0,0,0,1739034684,NULL,0,NULL,NULL),(3,1,10001,'Vilcom Employee Handbook Quiz Course','Vilcom_Quiz','','<h4><strong>Course Overview:</strong></h4>\r\n<p><br>This course is designed to ensure that all employees at Vilcom Networks Limited have a thorough understanding of the company\'s policies, procedures, and code of conduct as outlined in the <strong>Employee Handbook</strong>. The course consists of a series of quizzes that test employees\' knowledge of key topics, including employment basics, code of conduct, leave policies, performance management, disciplinary procedures, and health and safety guidelines.</p>\r\n<p>The quizzes are structured to reinforce learning, promote compliance, and ensure that employees are well-equipped to adhere to company standards and contribute to a positive and productive workplace.</p>',1,'singleactivity',1,1,1738875600,1775509200,0,0,0,0,0,1,1,NULL,0,0,0,'','','',1738827507,1738827507,0,1,0,1738844601,NULL,1,1,NULL);
